import json
import signal
import sys

from .httpapi import DeferredRequestStore, build_server

_USAGE = "usage: python -m forgetting_evidence health"
_SERVE_USAGE = (
    "usage: python -m forgetting_evidence serve <database> <address> <port>\n"
    "       python -m forgetting_evidence serve --db <database> "
    "--host <address> --port <port>"
)

_FLAG_ALIASES = {
    "--db": "db",
    "--database": "db",
    "--host": "host",
    "--address": "host",
    "--bind": "host",
    "--port": "port",
}
_POSITIONAL_FIELDS = ("db", "host", "port")


def _parse_serve_args(args: list[str]) -> dict[str, str] | None:
    values: dict[str, str] = {}
    positionals: list[str] = []
    index = 0
    while index < len(args):
        token = args[index]
        if "=" in token and token.split("=", 1)[0] in _FLAG_ALIASES:
            name, value = token.split("=", 1)
            field = _FLAG_ALIASES[name]
            if field in values or value == "":
                return None
            values[field] = value
        elif token in _FLAG_ALIASES:
            field = _FLAG_ALIASES[token]
            if field in values or index + 1 >= len(args):
                return None
            values[field] = args[index + 1]
            index += 1
        elif token.startswith("--"):
            return None
        else:
            positionals.append(token)
        index += 1
    if positionals and values:
        # Avoid ambiguity when both styles are mixed.
        return None
    if positionals:
        if len(positionals) != 3:
            return None
        values = dict(zip(_POSITIONAL_FIELDS, positionals))
    missing = [field for field in _POSITIONAL_FIELDS if not values.get(field)]
    if missing:
        return None
    return values


def _run_serve(args: list[str]) -> int:
    parsed = _parse_serve_args(args)
    if parsed is None:
        print(_SERVE_USAGE, file=sys.stderr)
        return 2
    try:
        port = int(parsed["port"])
    except ValueError:
        print(_SERVE_USAGE, file=sys.stderr)
        return 2
    if not 1 <= port <= 65535:
        print(_SERVE_USAGE, file=sys.stderr)
        return 2

    # The store opens (creating the file and required tables) at startup.
    # If the database cannot be created the service still binds: business
    # requests then answer 503 storage_unavailable and the store retries
    # initialization on the next request so a repaired path self-heals.
    store = DeferredRequestStore(parsed["db"])
    try:
        server = build_server(store, parsed["host"], port)
    except OSError:
        print("address_in_use", file=sys.stderr)
        return 1

    def _stop(_signum, _frame):
        raise KeyboardInterrupt

    previous_sigterm = signal.signal(signal.SIGTERM, _stop)
    try:
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass
        finally:
            server.server_close()
    finally:
        signal.signal(signal.SIGTERM, previous_sigterm)
    return 0


def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    if args == ["health"]:
        print(json.dumps({"service": "forgetting-evidence", "status": "ok"}, sort_keys=True))
        return 0
    if args and args[0] == "serve":
        return _run_serve(args[1:])
    print(_USAGE, file=sys.stderr)
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

def _render_audit_bundle(
    tenant_id: str,
    request_id: str,
    status: str,
    head: str,
    event_rows: tuple,
    anchor_rows: tuple,
    generation_rows: tuple,
) -> str:
    """Render the canonical bundle text for one request's settled chain.

    The content derives entirely from the persisted, already-assessed
    snapshot rows -- no clock, no randomness -- so repeated exports at
    the same request chain head are byte-identical. Only the secret
    generations this request's own anchors actually name are recorded:
    a later rotation or another request's events can never change what
    this request's proof needs.
    """
    events = sorted(
        (row for row in event_rows if row[0] == tenant_id and row[1] == request_id),
        key=lambda row: row[2],
    )
    anchors = sorted(
        (
            row
            for row in anchor_rows
            if row[1] == tenant_id and row[2] == request_id
        ),
        key=lambda row: row[3],
    )
    generation_records = {row[0]: (row[1], row[2]) for row in generation_rows}
    referenced = sorted(
        {(row[6] if row[6] is not None else 1) for row in anchors}
    )
    bundle = {
        "request_id": request_id,
        "status": status,
        "events": [
            {
                "seq": seq,
                "status": event_status,
                "occurred_at": occurred_at,
                "chain_hash": chain_hash,
            }
            for _t, _r, seq, event_status, occurred_at, chain_hash in events
        ],
        "chain": {
            "tenant_id": tenant_id,
            "event_count": len(events),
            "head": head,
        },
        "anchors": [
            {
                "seq": seq,
                "anchor_hmac": anchor_hmac,
                "key_generation": key_generation,
            }
            for _cs, _t, _r, seq, _eh, anchor_hmac, key_generation in anchors
        ],
        "generations": [
            {
                "generation": generation,
                "key_fingerprint": generation_records[generation][0],
                "effective_at": generation_records[generation][1],
            }
            for generation in referenced
            if generation in generation_records
        ],
    }
    return json.dumps(bundle, ensure_ascii=False, separators=(",", ":")) + "\n"

